// Generates docs/ADMIN_GUIDE.md and docs/CREATOR_GUIDE.md from the in-app guides (lib/guides/content), so the printed
// guides and the Help screens cannot drift apart. Links to app screens keep their path in brackets; links within a
// guide become plain text. Regenerated by npm run gen:sql; a unit test fails when a file is stale.
import { GUIDES } from "@/lib/guides";
import type { Block, Guide, GuideAudience } from "@/lib/guides/types";

export const GUIDE_DOCS = {
  "ADMIN_GUIDE.md": {
    title: "Eduwit Influencer Portal: staff guide",
    intro:
      "Everything staff do in the admin console, by role. The same text is in the console under Help, where each screen links to its section.",
    audiences: ["all_staff", "super_admin", "influencer_manager", "content_reviewer", "finance", "viewer"],
  },
  "CREATOR_GUIDE.md": {
    title: "Eduwit Influencer Portal: creator and agency guide",
    intro:
      "How creators (and the agencies they give access to) use the portal. The same text is in the portal under Help.",
    audiences: ["creator", "agency"],
  },
} as const satisfies Record<string, { title: string; intro: string; audiences: readonly GuideAudience[] }>;
export type GuideDoc = keyof typeof GUIDE_DOCS;

/** Inline text: app links show their path, in-guide anchors become plain text. */
function inline(s: string): string {
  return s
    .replace(/\[([^\]]+)\]\(#[^)]*\)/g, "$1")
    .replace(/\[([^\]]+)\]\((\/[^)]*)\)/g, "$1 (`$2`)")
    .replace(/\s+$/, "");
}

const cell = (s: string) => inline(s).replace(/\|/g, "\\|");

function block(b: Block): string {
  if ("p" in b) return inline(b.p);
  if ("h" in b) return `#### ${inline(b.h)}`;
  if ("steps" in b) return b.steps.map((x, i) => `${String(i + 1)}. ${inline(x)}`).join("\n");
  if ("list" in b) return b.list.map((x) => `- ${inline(x)}`).join("\n");
  if ("tip" in b) return `> **Tip:** ${inline(b.tip)}`;
  if ("warning" in b) return `> **Important:** ${inline(b.warning)}`;
  return [
    `| ${b.table.head.map(cell).join(" | ")} |`,
    `| ${b.table.head.map(() => "---").join(" | ")} |`,
    ...b.table.rows.map((r) => `| ${r.map(cell).join(" | ")} |`),
  ].join("\n");
}

function guide(g: Guide): string {
  const parts = [`## ${g.title}`, inline(g.summary)];
  for (const s of g.sections) parts.push(`### ${s.title}`, ...s.blocks.map(block));
  return parts.join("\n\n");
}

export function guideMarkdown(doc: GuideDoc): string {
  const d = GUIDE_DOCS[doc];
  const guides = GUIDES.filter((g) => (d.audiences as readonly GuideAudience[]).includes(g.audience));
  return [
    `# ${d.title}`,
    `<!-- Generated from lib/guides/content by npm run gen:sql. Do not edit by hand. -->`,
    d.intro,
    "## Contents",
    guides.map((g) => `- ${g.title}`).join("\n"),
    ...guides.map(guide),
  ]
    .join("\n\n")
    .concat("\n");
}
